esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: take an arbitrary deposit amount and then call withdrawAll
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // ensure starting credit value for this contract (msg.sender to C will be this contract)
        // read pre-deposit credit by making no call (we cannot read internal mapping directly),
        // so we first deposit zero to observe current behaviour indirectly: but deposit is state-changing.
        // Instead, we create an observation by depositing depositAmount and then reading effect.

        // Deposit an arbitrary amount to C (may be zero)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Record contract balance of C before withdrawAll
        uint cBalBefore = address(c).balance;

        // Try withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the attempt, read contract balance of C and use it as observable to reason about whether credit was cleared.
        uint cBalAfter = address(c).balance;

        // General rule to assert:
        // If withdrawAll succeeded (did not revert) then the caller's recorded credit was cleared to zero,
        // which implies that C's balance did not remain the same if pre-withdraw recorded credit > 0.
        // Because we cannot read the mapping directly, we assert the logical relation:
        // - If not reverted then after the call C's balance is <= cBalBefore and if depositAmount>0 then either cBalAfter == cBalBefore - depositAmount or cBalAfter <= cBalBefore (i.e., decreased by at least 0 up to depositAmount).
        // However to make a precise, non-trivial invariant observable only via public surface:
        // We assert: (1) if withdrawAll reverted then C's balance did not change; (2) if it succeeded then the caller's recorded credit is zero — we express (2) by the implication that a subsequent withdrawAll will not change C's balance (it will be a no-op when caller credit is zero).

        // Perform a second withdrawAll attempt to observe whether credit was cleared (if credit was zero this second call is a no-op and will leave balance unchanged and not revert)
        bool reverted2;
        uint cBalBefore2 = cBalAfter;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }
        uint cBalAfter2 = address(c).balance;

        // Assert the general rule: if the first withdrawAll reverted, then balances before/after it are equal;
        // otherwise (if first succeeded) the second withdrawAll must not decrease C's balance (since credit should be zero), i.e., cBalAfter2 == cBalBefore2 and it must not revert.
        assert( (reverted && cBalAfter == cBalBefore) || (!reverted && !reverted2 && cBalAfter2 == cBalBefore2) );
    }

    // accept Ether so withdraw transfers can reach this contract
    receive() external payable { }
}

